import { useEffect, useMemo, useRef, useState } from 'react';
import { Organismo } from '../types';
import catalogData from '../data/digital-index-catalog.json';
import { apiUrl } from '../lib/api';
import { Download, Lock, ArrowLeft, ExternalLink, Upload, ChevronLeft, ChevronRight, ChevronDown, ChevronUp, Info, CheckCircle2 } from 'lucide-react';

type Variable = (typeof catalogData)[number];
type Observation = { id:number; organismoId:number; variableId:string; nivel:number; fuente:'W'|'S'|'V'; fechaObservacion:string; evidencia?:string|null; notas?:string|null; usuario:string };
type Cut = { id:number; nombre:string; fecha:string; snapshot:Array<{organismoId:number;nombre:string;niveles:Record<string,number>;dimensionA:number;dimensionB:number;total:number}> };
type Extras = {tramites:Array<{id:number;fecha:string;nativos:number;integrados:number;fueraMiCorrientes:number;integradosLinks:string[];fueraMiCorrientesLinks:string[]}>;visitas:Array<{id:number;fecha:string;observaciones?:string|null}>};
type BaselinePreview = {applied:boolean;candidates:number;byVariable:Record<string,number>;completeApplied:boolean;completeCandidates:number;completeByVariable:Record<string,number>};
type Verification = {organismoId:number;variables:Record<string,{estado:'confirmado'|'sin_evidencia';nivel:number;usuario:string;fecha:string}>;cerradoPor?:string|null;cerradoAt?:string|null};
type VerificationSummary = {rows:Verification[];total:number;closed:number;cleanupReady:boolean};
const weights = catalogData as Variable[];
const dateToday = () => new Date().toLocaleDateString('en-CA');
const category = (score:number) => score < 25 ? 'Inicial' : score < 50 ? 'En desarrollo' : score < 75 ? 'Avanzado' : 'Consolidado';
const fmt = (n:number) => n.toLocaleString('es-AR', { minimumFractionDigits:1, maximumFractionDigits:1 });
const PROVINCIAL_UNIVERSE = 41;
const RANKING_PAGE_SIZE = 10;
function parseCsv(text:string):string[][] {
  const firstLine=text.split(/\r?\n/,1)[0];
  const delimiter=[',',';','\t'].sort((a,b)=>firstLine.split(b).length-firstLine.split(a).length)[0];
  const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;
  for(let i=0;i<text.length;i++){
    const char=text[i];
    if(char==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++;continue;}
    if(char==='"'){quoted=!quoted;continue;}
    if(char===delimiter&&!quoted){row.push(cell.trim());cell='';continue;}
    if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row);row=[];cell='';continue;}
    cell+=char;
  }
  row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row);return rows;
}
const normalizeHeader=(value:string)=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const isProvisional=(observation?:Observation)=>Boolean(observation?.notas?.includes('[base monitor anterior]'));
const parseLinkList=(value:string)=>value.split(/\r?\n/).map(link=>link.trim()).filter(Boolean);
const levelBadgeClass=(level:number,observed:boolean,provisional:boolean)=>{
  if(!observed)return 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400';
  const colors=['bg-rose-100 text-rose-900 dark:bg-rose-950/60 dark:text-rose-200','bg-orange-100 text-orange-900 dark:bg-orange-950/60 dark:text-orange-200','bg-yellow-100 text-yellow-900 dark:bg-yellow-950/60 dark:text-yellow-200','bg-emerald-100 text-emerald-900 dark:bg-emerald-950/60 dark:text-emerald-200'];
  return `${colors[level]??colors[0]} ${provisional?'font-bold ring-1 ring-amber-500 dark:ring-amber-400':'font-medium'}`;
};
const legacyFieldLabels:Partial<Record<keyof Organismo,string>>={
  tramitesMiCorrientes:'Trámites en Mi Corrientes', qTramitesOnline:'Cantidad de trámites online', tramitesOnline:'Trámites online',
  atencionDigital:'Atención digital', chatbot:'Chatbot', chatbotResena:'Reseña del chatbot', turnosOnline:'Turnos online',
  enlaceTurnosOnline:'Enlace de turnos', tieneWeb:'Tiene web oficial', tieneWebPropia:'Tiene web propia', enlaceWebGov:'Enlace web oficial',
  enlaceWebPropia:'Enlace web propia', enlaceWeb:'Enlace web', guiaTramites:'Guía de trámites', qTramitesGuia:'Cantidad en la guía',
  enlaceGuia:'Enlace de la guía', expedienteDigital:'Expediente digital', tieneDoco:'DOCO', usaSiif:'Uso de SIIF', resenaSiif:'Reseña de SIIF',
  firmaDigital:'Firma digital', resenaFirma:'Reseña de firma digital'
};
function legacySourceDetails(organismo:Organismo,observation?:Observation){
  const sourceFields=observation?.notas?.match(/Conversión orientativa desde ([^.]+)\./)?.[1].split(', ')??[];
  return sourceFields.map((field)=>{
    const key=field as keyof Organismo;
    const value=organismo[key];
    const rendered=typeof value==='boolean'?(value?'Sí':'No'):value===undefined||value===null||value===''?'Sin dato':String(value);
    return `${legacyFieldLabels[key]??field}: ${rendered}`;
  });
}

async function request<T>(path:string, token:string|null, init?:RequestInit):Promise<T> {
  const response = await fetch(apiUrl(path), { ...init, headers: { 'Content-Type':'application/json', ...(token ? { Authorization:`Bearer ${token}` } : {}), ...init?.headers } });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error || `Error ${response.status}`);
  return payload as T;
}

export default function DigitalIndex({ organismos, token, role, view='index' }: {organismos:Organismo[];token:string|null;role?:string;view?:'index'|'matrix'|'metrics'}) {
  const [observations,setObservations]=useState<Observation[]>([]);
  const [verification,setVerification]=useState<VerificationSummary|null>(null);
  const [verificationExpanded,setVerificationExpanded]=useState(true);
  const [cuts,setCuts]=useState<Cut[]>([]);
  const [extras,setExtras]=useState<Extras>({tramites:[],visitas:[]});
  const [baseline,setBaseline]=useState<BaselinePreview|null>(null);
  const [selectedId,setSelectedId]=useState<number|null>(null);
  const [expandedDimension,setExpandedDimension]=useState<'A'|'B'|null>('A');
  const [editingReview,setEditingReview]=useState<string|null>(null);
  const [cutName,setCutName]=useState('');
  const [cutDate,setCutDate]=useState(dateToday());
  const [notice,setNotice]=useState('');
  const [error,setError]=useState('');
  const [busy,setBusy]=useState(false);
  const importInput=useRef<HTMLInputElement>(null);
  const [sort,setSort]=useState<'total'|'A'|'B'>('total');
  const [rankingPage,setRankingPage]=useState(0);
  const [matrixFilter,setMatrixFilter]=useState('all');
  const [form,setForm]=useState({variableId:'A1',nivel:0,fuente:'W',fechaObservacion:dateToday(),evidencia:'',notas:''});
  const [tramiteForm,setTramiteForm]=useState({fecha:dateToday(),nativos:0,integrados:0,fueraMiCorrientes:0,integradosLinks:'',fueraMiCorrientesLinks:''});
  const [visitForm,setVisitForm]=useState({fecha:dateToday(),observaciones:''});
  const canEdit=role==='admin'||role==='editor';

  const refresh=async()=>{
    const [obs,closed]=await Promise.all([request<Observation[]>('/api/digital-index/observations',token),request<Cut[]>('/api/digital-index/cuts',token)]);
    setObservations(obs); setCuts(closed);
    if(canEdit&&token)setVerification(await request<VerificationSummary>('/api/digital-index/verifications',token));
  };
  useEffect(()=>{ refresh().catch(e=>setError(e.message)); },[]);
  useEffect(()=>{if(canEdit&&token)Promise.all([request<Omit<BaselinePreview,'completeApplied'|'completeCandidates'|'completeByVariable'>>('/api/digital-index/legacy-baseline',token),request<{applied:boolean;candidates:number;byVariable:Record<string,number>}>('/api/digital-index/legacy-complete',token)]).then(([base,complete])=>setBaseline({...base,completeApplied:complete.applied,completeCandidates:complete.candidates,completeByVariable:complete.byVariable})).catch(e=>setError(e.message));},[canEdit,token]);
  useEffect(()=>{setEditingReview(null);if(selectedId!==null)request<Extras>(`/api/digital-index/organismos/${selectedId}/extra`,token).then(setExtras).catch(e=>setError(e.message));},[selectedId]);
  useEffect(()=>{setSelectedId(null);setRankingPage(0);},[view]);

  const model=useMemo(()=>{
    const rows=organismos.map(org=>{
      const latest:Record<string,Observation>={};
      for(const item of observations.filter(o=>o.organismoId===org.id)){
        const prev=latest[item.variableId];
        if(!prev||item.fechaObservacion>prev.fechaObservacion||(item.fechaObservacion===prev.fechaObservacion&&item.fuente==='V'&&prev.fuente!=='V')||(item.fechaObservacion===prev.fechaObservacion&&item.fuente===prev.fuente&&item.id>prev.id)) latest[item.variableId]=item;
      }
      const levels=Object.fromEntries(weights.map(v=>[v.id,latest[v.id]?.nivel??0])) as Record<string,number>;
      const dimensionA=weights.filter(v=>v.dimension==='A').reduce((s,v)=>s+v.points*levels[v.id]/3,0);
      const dimensionB=weights.filter(v=>v.dimension==='B').reduce((s,v)=>s+v.points*levels[v.id]/3,0);
      return {org,latest,levels,dimensionA,dimensionB,total:dimensionA+dimensionB};
    });
    const coverage=weights.map(v=>({variable:v,count:rows.filter(r=>r.levels[v.id]>=(v.id==='B1'||v.scale==='binary'?3:2)).length,observed:rows.filter(r=>Boolean(r.latest[v.id])).length}));
    return {rows,index:rows.reduce((s,r)=>s+r.total,0)/PROVINCIAL_UNIVERSE,dimensionA:rows.reduce((s,r)=>s+r.dimensionA,0)/PROVINCIAL_UNIVERSE,dimensionB:rows.reduce((s,r)=>s+r.dimensionB,0)/PROVINCIAL_UNIVERSE,coverage};
  },[organismos,observations]);
  const selected=model.rows.find(row=>row.org.id===selectedId);
  const selectedVerification=verification?.rows.find(row=>row.organismoId===selectedId);
  const reviewedCount=Object.keys(selectedVerification?.variables??{}).length;
  const verificationClosed=Boolean(selectedVerification?.cerradoAt);
  const allReviewed=reviewedCount>=weights.length;
  useEffect(()=>{setVerificationExpanded(!allReviewed&&!verificationClosed);},[selectedId,allReviewed,verificationClosed]);
  const sorted=[...model.rows].sort((a,b)=>sort==='A'?b.dimensionA-a.dimensionA:sort==='B'?b.dimensionB-a.dimensionB:b.total-a.total);
  const pageCount=Math.max(1,Math.ceil(sorted.length/RANKING_PAGE_SIZE));
  const pageRows=sorted.slice(rankingPage*RANKING_PAGE_SIZE,(rankingPage+1)*RANKING_PAGE_SIZE);
  const matrixRows=useMemo(()=>model.rows.filter(row=>matrixFilter==='all'||(matrixFilter==='pending'?weights.some(variable=>isProvisional(row.latest[variable.id])):matrixFilter==='validated'?weights.some(variable=>row.latest[variable.id]&&!isProvisional(row.latest[variable.id])):isProvisional(row.latest[matrixFilter]))),[model.rows,matrixFilter]);
  const categoryCounts=['Inicial','En desarrollo','Avanzado','Consolidado'].map(name=>({name,count:model.rows.filter(row=>category(row.total)===name).length}));
  const migratedCount=useMemo(()=>observations.filter(item=>item.notas?.includes('[base monitor anterior]')).length,[observations]);

  const saveObservation=async()=>{
    if(!selected)return;
    setError('');setNotice('');setBusy(true);
    try{
      await request('/api/digital-index/observations',token,{method:'POST',body:JSON.stringify({organismoId:selected.org.id,...form,nivel:Number(form.nivel)})});
      await refresh();setNotice('Observación agregada al historial.');setForm(f=>({...f,evidencia:'',notas:''}));
    }catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const reviewVariable=async(variableId:string,estado:'confirmado'|'sin_evidencia')=>{
    if(!selected)return;setBusy(true);setError('');setNotice('');
    try{await request(`/api/digital-index/organismos/${selected.org.id}/verification`,token,{method:'POST',body:JSON.stringify({variableId,estado})});await refresh();setEditingReview(null);setNotice('Verificación registrada.');}
    catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const closeVerification=async()=>{
    if(!selected)return;setBusy(true);setError('');setNotice('');
    try{await request(`/api/digital-index/organismos/${selected.org.id}/verification/close`,token,{method:'POST',body:'{}'});await refresh();setNotice('Verificación del organismo cerrada.');}
    catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const cleanupProvisional=async()=>{
    if(!window.confirm('Se eliminarán únicamente las observaciones marcadas como base provisoria. Las observaciones confirmadas, corregidas y el registro de verificación se conservarán. ¿Continuar?'))return;
    setBusy(true);setError('');setNotice('');
    try{const result=await request<{deleted:number}>('/api/digital-index/provisional-observations',token,{method:'DELETE'});await refresh();setNotice(`Se retiraron ${result.deleted} observaciones provisorias.`);}
    catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const saveExtra=async(kind:'tramites'|'visitas')=>{
    if(!selected)return;setBusy(true);setError('');setNotice('');
    try{
      const payload=kind==='tramites'?{...tramiteForm,integradosLinks:parseLinkList(tramiteForm.integradosLinks),fueraMiCorrientesLinks:parseLinkList(tramiteForm.fueraMiCorrientesLinks)}:visitForm;
      await request(`/api/digital-index/organismos/${selected.org.id}/${kind}`,token,{method:'POST',body:JSON.stringify(payload)});
      const data=await request<Extras>(`/api/digital-index/organismos/${selected.org.id}/extra`,token);setExtras(data);setNotice(kind==='tramites'?'Detalle de trámites agregado.':'Visita agregada al historial.');
    }catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const closeCut=async()=>{
    setError('');setNotice('');setBusy(true);
    try{await request('/api/digital-index/cuts',token,{method:'POST',body:JSON.stringify({nombre:cutName,fecha:cutDate})});await refresh();setNotice('Corte cerrado y congelado.');setCutName('')}
    catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const migrateBaseline=async()=>{
    if(!baseline?.candidates)return;setBusy(true);setError('');setNotice('');
    try{
      const result=await request<{inserted:number}>('/api/digital-index/legacy-baseline',token,{method:'POST',body:JSON.stringify({})});
      await Promise.all([refresh(),request<BaselinePreview>('/api/digital-index/legacy-baseline',token).then(setBaseline)]);
      setNotice(`Línea de base incorporada: ${result.inserted} observaciones justificadas. Las demás variables quedan sin observar.`);
    }catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const completeLegacyMigration=async()=>{
    if(!baseline?.completeCandidates)return;setBusy(true);setError('');setNotice('');
    try{
      const result=await request<{inserted:number;updated:number}>('/api/digital-index/legacy-complete',token,{method:'POST',body:JSON.stringify({})});
      await Promise.all([refresh(),request<{applied:boolean;candidates:number;byVariable:Record<string,number>}>('/api/digital-index/legacy-complete',token).then(complete=>setBaseline(current=>current?{...current,completeApplied:complete.applied,completeCandidates:complete.candidates,completeByVariable:complete.byVariable}:current))]);
      setNotice(`Migración integral completada: ${result.inserted} observaciones agregadas y ${result.updated} ajustadas con campos legados. Quedan señaladas para revisión de cada organismo.`);
    }catch(e:any){setError(e.message)}finally{setBusy(false)}
  };
  const importCsv=async(file:File)=>{
    setBusy(true);setError('');setNotice('');
    try{
      const table=parseCsv((await file.text()).replace(/^\uFEFF/,''));
      if(table.length<2)throw new Error('El CSV está vacío o no tiene filas de datos.');
      const headers=table[0].map(normalizeHeader), col=(...names:string[])=>headers.findIndex(h=>names.includes(h));
      const cOrg=col('organismoid','organismo'),cVar=col('variableid','variable'),cLevel=col('nivel'),cSource=col('fuente'),cDate=col('fechaobservacion','fecha'),cEvidence=col('evidencia'),cNotes=col('notas','observaciones');
      if([cOrg,cVar,cLevel,cSource,cDate].some(i=>i<0))throw new Error('Faltan columnas requeridas: organismo_id, variable_id, nivel, fuente y fecha_observacion.');
      const byName=new Map(organismos.map(org=>[org.nombre.trim().toLocaleLowerCase(),org.id]));
      const rows=table.slice(1).map(line=>{const get=(i:number)=>i<0?'':line[i]??'';const rawOrg=get(cOrg);const orgId=Number(rawOrg)||byName.get(rawOrg.trim().toLocaleLowerCase());return {organismoId:orgId,variableId:get(cVar).trim().toUpperCase(),nivel:Number(get(cLevel)),fuente:get(cSource).trim().toUpperCase(),fechaObservacion:get(cDate).trim(),evidencia:get(cEvidence),notas:get(cNotes)};});
      const result=await request<{inserted:number}>('/api/digital-index/observations/import',token,{method:'POST',body:JSON.stringify({rows})});
      await refresh();setNotice(`Se importaron ${result.inserted} observaciones.`);
    }catch(e:any){setError(e.message)}finally{setBusy(false);if(importInput.current)importInput.current.value='';}
  };
  const exportCsv=(cut?:Cut)=>{
    const source=cut?.snapshot.map(r=>({org:organismos.find(o=>o.id===r.organismoId),levels:r.niveles,latest:undefined as Record<string,Observation>|undefined}))??model.rows.map(r=>({org:r.org,levels:r.levels,latest:r.latest}));
    const lines=[['organismo_id','organismo','variable_id','variable','dimension','nivel','puntaje_aportado','fuente','fecha_observacion','evidencia']];
    for(const row of source)for(const variable of weights){const obs=row.latest?.[variable.id];
      lines.push([String(row.org?.id??''),row.org?.nombre??'',variable.id,variable.name,variable.dimension,String(row.levels[variable.id]??0),fmt(variable.points*(row.levels[variable.id]??0)/3),obs?.fuente??'',obs?.fechaObservacion??'',obs?.evidencia??'']);}
    const csv='\uFEFF'+lines.map(line=>line.map(cell=>`"${String(cell).replaceAll('"','""')}"`).join(';')).join('\r\n');
    const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`indice-digital-${cut?.nombre??'vigente'}.csv`;a.click();URL.revokeObjectURL(url);
  };

  if(selected)return <section className="space-y-5">
    <button onClick={()=>setSelectedId(null)} className="inline-flex items-center gap-2 text-sm font-semibold text-slate-600 hover:text-blue-700 dark:text-slate-300"><ArrowLeft size={16}/>Volver al índice</button>
    <div className="rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900">
      <div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-600">Ficha del organismo</p><h2 className="mt-1 text-2xl font-bold">{selected.org.nombre}</h2><p className="mt-1 text-sm text-slate-500">{selected.org.tipo}</p></div><div className="text-right"><strong className="text-3xl">{fmt(selected.total)}</strong><span className="ml-1 text-slate-500">/ 100</span><p className="text-sm font-semibold text-blue-700">{category(selected.total)}</p></div></div>
      <div className="mt-5 grid gap-3 sm:grid-cols-2"><ScoreBar title="A · Servicios al ciudadano" score={selected.dimensionA} max={60}/><ScoreBar title="B · Gestión interna y capacidades" score={selected.dimensionB} max={40}/></div>
    </div>
    <div className="space-y-5">{(['A','B'] as const).map(dimension=>{const variables=weights.filter(variable=>variable.dimension===dimension);const isCitizen=dimension==='A';return <section key={dimension} className={`overflow-hidden rounded-2xl border ${isCitizen?'border-blue-200 dark:border-blue-900':'border-emerald-200 dark:border-emerald-900'}`}><button type="button" aria-expanded={expandedDimension===dimension} onClick={()=>setExpandedDimension(current=>current===dimension?null:dimension)} className={`flex w-full items-center justify-between px-4 py-3 text-left ${isCitizen?'bg-blue-100 text-blue-950 dark:bg-blue-950/70 dark:text-blue-100':'bg-emerald-100 text-emerald-950 dark:bg-emerald-950/70 dark:text-emerald-100'}`}><div><h3 className="font-bold">{dimension} · {isCitizen?'Servicios al ciudadano':'Gestión interna y capacidades'}</h3><p className="mt-0.5 text-xs opacity-80">{variables.length} variables · Máximo {isCitizen?60:40} puntos</p></div><strong className="text-xl">{fmt(isCitizen?selected.dimensionA:selected.dimensionB)}<span className="ml-1 text-sm font-normal opacity-70">/ {isCitizen?60:40}</span></strong><span className="ml-3 shrink-0 text-slate-500">{expandedDimension===dimension?<ChevronUp size={18}/>:<ChevronDown size={18}/>}</span></button>{expandedDimension===dimension&&<div className="overflow-x-auto bg-white dark:bg-slate-900"><table className="w-full min-w-[1050px] table-fixed text-left text-sm"><colgroup><col className="w-52"/><col className="w-28"/><col className="w-[26%]"/><col className="w-[25%]"/><col className="w-[30%]"/></colgroup><thead className="bg-slate-50 text-[11px] uppercase tracking-wide text-slate-500 dark:bg-slate-950"><tr><th className="p-3">Variable</th><th className="p-3">Nivel</th><th className="p-3">Qué significa</th><th className="p-3">Siguiente nivel</th><th className="p-3">Revisión y evidencia</th></tr></thead><tbody>{variables.map(v=>{const level=selected.levels[v.id],obs=selected.latest[v.id],provisional=isProvisional(obs),legacyDetails=legacySourceDetails(selected.org,obs),review=selectedVerification?.variables?.[v.id];const note=provisional&&legacyDetails.length?legacyDetails.join(' · '):obs?.notas;const nextLevel=level>=3?'Nivel máximo':v.id==='B1'&&level===0?'Nivel 3 si está en uso en todo el organismo':v.id==='A3'&&level===2?'Pendiente de definición':v.levels[String(level+1) as keyof typeof v.levels];return <tr key={v.id} className={`border-t align-top ${isCitizen?'border-blue-100 dark:border-blue-950':'border-emerald-100 dark:border-emerald-950'}`}><td className={`p-3 ${isCitizen?'bg-blue-50/40 dark:bg-blue-950/15':'bg-emerald-50/40 dark:bg-emerald-950/15'}`}><strong className={isCitizen?'text-blue-800 dark:text-blue-200':'text-emerald-800 dark:text-emerald-200'}>{v.id} · {v.name}</strong><span className="mt-1 block text-xs text-slate-500">Máximo {v.points} pts</span></td><td className="p-3"><span className={`inline-flex rounded-lg px-2.5 py-1.5 text-sm font-bold ${levelBadgeClass(level,Boolean(obs),provisional)}`}>{obs?`N${level}${provisional?'*':''}`:'S/O'}</span><span className="mt-1 block text-xs text-slate-500">{obs?`Nivel ${level}`:'Sin observar'}</span></td><td className="p-3 text-sm text-slate-700 dark:text-slate-200">{obs?v.levels[String(level) as keyof typeof v.levels]:'Sin observación registrada; se computa como nivel 0.'}</td><td className="p-3 text-sm text-slate-600 dark:text-slate-300">{nextLevel}</td><td className="p-3"><div className="text-xs">{review?<strong className="text-emerald-800 dark:text-emerald-300">{review.estado==='confirmado'?'Confirmado':'Sin evidencia'} · {review.usuario}</strong>:provisional?<strong className="text-amber-800 dark:text-amber-300">Pendiente de validación</strong>:obs?<strong className="text-blue-800 dark:text-blue-300">Observación posterior</strong>:<strong className="text-slate-500">Sin observar</strong>}</div>{note&&<details className="mt-1 text-xs text-slate-600 dark:text-slate-300"><summary className="cursor-pointer font-medium text-blue-700 dark:text-blue-300">Ver detalle</summary><p className="mt-1 leading-relaxed">{note}</p></details>}<div className="mt-2 flex flex-wrap gap-x-3 gap-y-1 text-[11px] text-slate-500"><span>Fuente: {obs?.fuente??'—'}</span><span>{obs?.fechaObservacion??'Sin fecha'}</span>{obs?.evidencia&&<a href={obs.evidencia} target="_blank" rel="noreferrer" className="font-semibold text-blue-700 underline dark:text-blue-300">Ver evidencia</a>}</div></td></tr>})}</tbody></table></div>}</section>})}</div>
    {canEdit&&verification&&<section className={`rounded-2xl border p-4 ${verificationClosed?'border-emerald-200 bg-emerald-50/70 dark:border-emerald-900 dark:bg-emerald-950/20':'border-amber-200 bg-amber-50/70 dark:border-amber-900 dark:bg-amber-950/20'}`}>{verificationClosed?<div className="flex items-center gap-2 text-sm font-semibold text-emerald-800 dark:text-emerald-200"><CheckCircle2 size={18}/><span>Verificación cerrada por {selectedVerification?.cerradoPor} · {reviewedCount}/11 revisadas</span></div>:<><div className="flex flex-wrap items-center justify-between gap-3"><button type="button" aria-expanded={verificationExpanded} onClick={()=>setVerificationExpanded(value=>!value)} className="flex min-w-0 flex-1 items-start gap-3 text-left"><span className="mt-0.5 text-amber-800 dark:text-amber-200">{verificationExpanded?<ChevronUp size={18}/>:<ChevronDown size={18}/>}</span><span><strong className="block">Verificación de datos migrados</strong><span className="mt-1 block text-sm text-slate-600 dark:text-slate-300">{allReviewed?'Las 11 variables están revisadas. Cerrá la verificación para finalizar.':'Confirmá el nivel vigente o indicá si no encontraste evidencia.'}</span></span></button><span className="shrink-0 text-sm font-semibold">{reviewedCount}/11 revisadas</span>{allReviewed&&<button disabled={busy} onClick={closeVerification} className="rounded-lg bg-amber-800 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">Cerrar verificación</button>}</div>{verificationExpanded&&<div className="mt-4 space-y-2">{weights.map(v=>{const review=selectedVerification?.variables?.[v.id],editing=editingReview===v.id;return <div key={v.id} className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-white p-3 text-sm dark:bg-slate-900"><span className="min-w-0"><strong>{v.id} · {v.name}</strong>{review?<span className="ml-2 inline-flex items-center gap-1 rounded-full bg-emerald-100 px-2 py-0.5 text-xs font-semibold text-emerald-800 dark:bg-emerald-950 dark:text-emerald-200"><CheckCircle2 size={12}/>{review.estado==='confirmado'?'Confirmado':'Sin evidencia'} · {review.usuario}</span>:<span className="ml-2 text-xs text-slate-500">Pendiente</span>}</span>{review&&!editing?<button disabled={busy||verificationClosed} onClick={()=>setEditingReview(v.id)} className="rounded-lg border px-3 py-1.5 text-xs font-semibold disabled:opacity-40">Modificar</button>:<div className="flex flex-wrap gap-2"><button disabled={busy||verificationClosed||!selected.latest[v.id]} onClick={()=>reviewVariable(v.id,'confirmado')} className="rounded-lg border px-3 py-1.5 text-xs font-semibold disabled:opacity-40">Confirmar nivel {selected.levels[v.id]}</button><button disabled={busy||verificationClosed} onClick={()=>reviewVariable(v.id,'sin_evidencia')} className="rounded-lg border px-3 py-1.5 text-xs font-semibold disabled:opacity-40">Sin evidencia</button>{review&&<button disabled={busy} onClick={()=>setEditingReview(null)} className="rounded-lg border px-3 py-1.5 text-xs font-semibold disabled:opacity-40">Cancelar</button>}</div>}</div>})}</div>}</>}</section>}
    <div className="grid gap-4 lg:grid-cols-2"><section className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><div><h3 className="font-bold">Trámites en Mi Corrientes y otros canales</h3><p className="mt-1 text-xs text-slate-500">Registrá la cantidad vigente y agregá enlaces para respaldar los trámites integrados o externos.</p></div><details className="mt-3 rounded-lg bg-slate-50 px-3 py-2 text-xs text-slate-600 dark:bg-slate-950 dark:text-slate-300"><summary className="flex cursor-pointer items-center gap-2 font-semibold"><Info size={14}/> ¿Qué significa cada categoría y para qué se piden enlaces?</summary><ul className="mt-2 list-disc space-y-1 pl-4"><li><strong>Nativos:</strong> se inician y completan dentro de Mi Corrientes.</li><li><strong>Integrados o federados:</strong> Mi Corrientes deriva a otro sistema conectado. El enlace permite identificarlo.</li><li><strong>Online fuera de Mi Corrientes:</strong> el organismo ofrece el trámite en su propio sitio o en otra plataforma. El enlace sirve como evidencia.</li></ul><p className="mt-2">Cargá una URL por línea. Así se puede comprobar qué trámites forman parte de cada cantidad.</p></details>{extras.tramites[0]&&<div className="mt-3 rounded-lg border border-slate-200 p-3 text-sm dark:border-slate-800"><p><strong>Último registro ({extras.tramites[0].fecha}):</strong> {extras.tramites[0].nativos} nativos · {extras.tramites[0].integrados} integrados o federados · {extras.tramites[0].fueraMiCorrientes} online fuera de Mi Corrientes.</p><div className="mt-2 grid gap-2 sm:grid-cols-2">{([{title:'Enlaces integrados o federados',links:extras.tramites[0].integradosLinks??[]},{title:'Enlaces fuera de Mi Corrientes',links:extras.tramites[0].fueraMiCorrientesLinks??[]}] as const).map(group=><div key={group.title}><p className="text-xs font-semibold text-slate-600 dark:text-slate-300">{group.title}</p>{group.links.length?<ul className="mt-1 space-y-1">{group.links.map(link=><li key={link} className="truncate"><a href={link} target="_blank" rel="noreferrer" className="text-blue-700 underline dark:text-blue-300">{link}</a></li>)}</ul>:<p className="mt-1 text-xs text-slate-400">Sin enlaces cargados</p>}</div>)}</div></div>}{canEdit&&<div className="mt-4 space-y-3 border-t border-slate-200 pt-4 dark:border-slate-800"><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-semibold">Fecha del relevamiento<input className="field mt-1" type="date" value={tramiteForm.fecha} onChange={e=>setTramiteForm({...tramiteForm,fecha:e.target.value})}/></label>{(['nativos','integrados','fueraMiCorrientes'] as const).map((key,i)=><label key={key} className="text-xs font-semibold">{['Trámites nativos','Integrados o federados','Online fuera de Mi Corrientes'][i]}<input className="field mt-1" type="number" min="0" value={tramiteForm[key]} onChange={e=>setTramiteForm({...tramiteForm,[key]:Number(e.target.value)})}/></label>)}</div><div className="grid gap-3 sm:grid-cols-2"><label className="text-xs font-semibold">Links integrados o federados<span className="mt-1 block font-normal text-slate-500">Una URL por línea; pegá la dirección del sistema o trámite.</span><textarea className="field mt-1 min-h-20" value={tramiteForm.integradosLinks} onChange={e=>setTramiteForm({...tramiteForm,integradosLinks:e.target.value})} placeholder="https://..."/></label><label className="text-xs font-semibold">Links online fuera de Mi Corrientes<span className="mt-1 block font-normal text-slate-500">Una URL por línea; pegá la dirección pública del trámite.</span><textarea className="field mt-1 min-h-20" value={tramiteForm.fueraMiCorrientesLinks} onChange={e=>setTramiteForm({...tramiteForm,fueraMiCorrientesLinks:e.target.value})} placeholder="https://..."/></label></div><button disabled={busy} onClick={()=>saveExtra('tramites')} className="rounded-lg bg-blue-700 px-3 py-2 text-sm font-semibold text-white disabled:opacity-50">Guardar cantidades y enlaces</button></div>}</section>
      <section className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h3 className="font-bold">Historial de visitas</h3>{extras.visitas.length?<ul className="mt-2 space-y-2">{extras.visitas.map(visit=><li key={visit.id} className="rounded-lg bg-slate-50 p-3 text-sm dark:bg-slate-950"><strong>{visit.fecha}</strong>{visit.observaciones&&<p className="mt-1 text-slate-600 dark:text-slate-300">{visit.observaciones}</p>}</li>)}</ul>:<p className="mt-2 text-sm text-slate-500">Todavía no hay visitas registradas.</p>}{canEdit&&<div className="mt-3 space-y-2"><input className="field" type="date" value={visitForm.fecha} onChange={e=>setVisitForm({...visitForm,fecha:e.target.value})}/><textarea className="field" placeholder="Procesos relevados o rediseñados" value={visitForm.observaciones} onChange={e=>setVisitForm({...visitForm,observaciones:e.target.value})}/><button disabled={busy} onClick={()=>saveExtra('visitas')} className="rounded-lg bg-blue-700 px-3 py-2 text-sm font-semibold text-white">Registrar visita</button></div>}</section></div>
    {canEdit&&<div className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h3 className="font-bold">Agregar observación</h3><p className="mb-4 text-xs text-slate-500">Cada carga agrega un registro nuevo; no reemplaza observaciones anteriores.</p><div className="grid gap-3 md:grid-cols-2">
      <label className="text-xs font-semibold">Variable<select className="field" value={form.variableId} onChange={e=>setForm({...form,variableId:e.target.value})}>{weights.map(v=><option key={v.id} value={v.id}>{v.id} · {v.name}</option>)}</select></label>
      <label className="text-xs font-semibold">Nivel<select className="field" value={form.nivel} onChange={e=>setForm({...form,nivel:Number(e.target.value)})}>{(form.variableId==='A5'||form.variableId==='B1'?[0,3]:[0,1,2,3]).map(n=><option key={n} value={n}>Nivel {n} — {weights.find(v=>v.id===form.variableId)?.levels[String(n) as keyof typeof weights[number]['levels']]}</option>)}</select></label>
      <label className="text-xs font-semibold">Fuente<select className="field" value={form.fuente} onChange={e=>setForm({...form,fuente:e.target.value})}><option value="W">W · Web y Mi Corrientes</option><option value="S">S · Sistemas provinciales</option><option value="V">V · Visita al organismo</option></select></label>
      <label className="text-xs font-semibold">Fecha de observación<input className="field" type="date" value={form.fechaObservacion} onChange={e=>setForm({...form,fechaObservacion:e.target.value})}/></label>
      <label className="text-xs font-semibold">Evidencia (enlace)<input className="field" type="url" value={form.evidencia} onChange={e=>setForm({...form,evidencia:e.target.value})} placeholder="https://…"/></label>
      <label className="text-xs font-semibold">Notas<textarea className="field" value={form.notas} onChange={e=>setForm({...form,notas:e.target.value})}/></label></div>
      {form.variableId==='A3'&&form.nivel===3&&<p className="mt-2 text-xs text-amber-700">El nivel 3 no se puede cargar hasta que se defina su criterio.</p>}
      <button disabled={busy||(form.variableId==='A3'&&form.nivel===3)} onClick={saveObservation} className="mt-4 rounded-lg bg-blue-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">Guardar observación</button>
    </div>}
    {error&&<p className="text-sm text-red-700">{error}</p>}{notice&&<p className="text-sm text-emerald-700">{notice}</p>}
  </section>;

  if(view==='matrix')return <section className="space-y-5">
    <div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Datos del índice</p><h2 className="mt-1 text-2xl font-extrabold">Matriz de las 11 variables</h2><p className="mt-1 text-sm text-slate-500">Los 41 organismos en una sola lista. Las variables están agrupadas por dimensión e incluyen su nombre y puntaje. “Sin observar” se calcula como nivel 0.</p></div>
    {canEdit&&verification&&<div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 dark:border-amber-900 dark:bg-amber-950/20"><div><strong className="text-sm">Verificaciones cerradas: {verification.closed}/{verification.total}</strong><p className="mt-1 text-xs text-slate-600 dark:text-slate-300">La base provisoria se podrá retirar cuando todas las fichas estén cerradas.</p></div>{role==='admin'&&<button disabled={!verification.cleanupReady||busy} onClick={cleanupProvisional} className="rounded-lg border border-amber-800 px-3 py-2 text-sm font-semibold text-amber-900 disabled:opacity-40 dark:text-amber-100">Retirar base provisoria</button>}</div>}
    <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white px-4 py-3 dark:border-slate-800 dark:bg-slate-900"><div className="text-xs text-slate-600 dark:text-slate-300"><p><strong>N*</strong> indica un nivel migrado pendiente de validación; <strong>N</strong> indica una observación posterior; S/O significa sin observar.</p><p className="mt-1">Escala: <strong className="text-rose-700 dark:text-rose-300">N0</strong> bajo, <strong className="text-orange-700 dark:text-orange-300">N1</strong>, <strong className="text-yellow-700 dark:text-yellow-300">N2</strong>, <strong className="text-emerald-700 dark:text-emerald-300">N3</strong> alto. El borde ámbar marca los niveles pendientes.</p><p className="mt-1">Mostrando {matrixRows.length} de {model.rows.length} organismos. Seleccioná una fila para ver el dato legado y registrar una corrección.</p></div><label className="text-xs font-semibold">Filtrar revisión<select className="field mt-1 min-w-64" value={matrixFilter} onChange={event=>setMatrixFilter(event.target.value)}><option value="all">Todos los organismos</option><option value="pending">Con algún nivel pendiente</option><option value="validated">Con observaciones posteriores</option><optgroup label="Pendiente por variable">{weights.map(variable=><option key={variable.id} value={variable.id}>{variable.id} · {variable.name}</option>)}</optgroup></select></label></div>
    <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900"><table className="w-full min-w-[2050px] text-left text-xs"><thead className="text-slate-600 dark:text-slate-300"><tr><th rowSpan={2} scope="col" className="sticky left-0 z-20 min-w-64 border-b border-slate-200 bg-slate-50 p-3 align-bottom dark:border-slate-800 dark:bg-slate-950">Organismo</th><th colSpan={weights.filter(v=>v.dimension==='A').length} scope="colgroup" className="border-b border-r border-blue-200 bg-blue-100 px-3 py-2 text-center font-bold text-blue-900 dark:border-blue-900 dark:bg-blue-950/80 dark:text-blue-100">A · Servicios al ciudadano</th><th colSpan={weights.filter(v=>v.dimension==='B').length} scope="colgroup" className="border-b border-r border-emerald-200 bg-emerald-100 px-3 py-2 text-center font-bold text-emerald-900 dark:border-emerald-900 dark:bg-emerald-950/80 dark:text-emerald-100">B · Gestión interna y capacidades</th><th rowSpan={2} scope="col" className="border-b border-slate-200 bg-slate-50 p-3 align-bottom dark:border-slate-800 dark:bg-slate-950">A / 60</th><th rowSpan={2} scope="col" className="border-b border-slate-200 bg-slate-50 p-3 align-bottom dark:border-slate-800 dark:bg-slate-950">B / 40</th><th rowSpan={2} scope="col" className="border-b border-slate-200 bg-slate-50 p-3 align-bottom dark:border-slate-800 dark:bg-slate-950">Total</th></tr><tr>{weights.map(v=><th key={v.id} scope="col" className={`min-w-36 border-b border-slate-200 p-3 text-center align-top dark:border-slate-800 ${v.dimension==='A'?'border-r border-blue-100 bg-blue-50/70 dark:border-blue-950 dark:bg-blue-950/30':'border-r border-emerald-100 bg-emerald-50/70 dark:border-emerald-950 dark:bg-emerald-950/30'}`}><span className={`block font-bold ${v.dimension==='A'?'text-blue-800 dark:text-blue-200':'text-emerald-800 dark:text-emerald-200'}`}>{v.id}</span><span className="mt-1 block min-h-8 font-medium leading-tight text-slate-700 dark:text-slate-200">{v.name}</span><span className="mt-1 block font-normal text-slate-500">{v.points} pts</span></th>)}</tr></thead><tbody>{matrixRows.map(row=><tr key={row.org.id} onClick={()=>setSelectedId(row.org.id)} className="cursor-pointer border-t border-slate-100 hover:bg-slate-50 dark:border-slate-800 dark:hover:bg-slate-800"><td className="sticky left-0 z-10 border-r border-slate-100 bg-white p-3 font-semibold dark:border-slate-800 dark:bg-slate-900">{row.org.nombre}</td>{weights.map(v=>{const obs=row.latest[v.id],level=row.levels[v.id],provisional=isProvisional(obs);return <td key={v.id} className={`border-r p-3 text-center ${v.dimension==='A'?'border-blue-100/80 bg-blue-50/25 dark:border-blue-950/70 dark:bg-blue-950/10':'border-emerald-100/80 bg-emerald-50/25 dark:border-emerald-950/70 dark:bg-emerald-950/10'}`}><span className={`rounded px-2 py-1 ${levelBadgeClass(level,Boolean(obs),provisional)}`} title={obs?`${provisional?'Pendiente de validación · ':''}${obs.fuente} · ${obs.fechaObservacion}`:'Sin observar'}>{obs?`N${level}${provisional?'*':''}`:'S/O'}</span></td>})}<td className="p-3">{fmt(row.dimensionA)}</td><td className="p-3">{fmt(row.dimensionB)}</td><td className="p-3 font-bold">{fmt(row.total)}</td></tr>)}</tbody></table></div>
    {error&&<p className="text-sm text-red-700">{error}</p>}
  </section>;

  if(view==='metrics')return <section className="space-y-5">
    <div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Lectura del índice</p><h2 className="mt-1 text-2xl font-extrabold">Métricas de digitalización</h2><p className="mt-1 text-sm text-slate-500">Indicadores calculados desde las mismas observaciones del índice provincial.</p></div>
    <div className="grid gap-4 md:grid-cols-3"><article className="rounded-2xl bg-slate-900 p-5 text-white"><p className="text-xs uppercase tracking-wider text-slate-300">Índice provincial</p><div className="mt-2 text-4xl font-extrabold">{fmt(model.index)}<span className="text-lg"> / 100</span></div><p className="mt-1 text-sm text-blue-200">{category(model.index)}</p></article><ScoreBar title="A · Servicios al ciudadano" score={model.dimensionA} max={60}/><ScoreBar title="B · Gestión interna y capacidades" score={model.dimensionB} max={40}/></div>
    <div className="grid gap-5 lg:grid-cols-2"><div className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h3 className="font-bold">Organismos por categoría</h3><div className="mt-4 space-y-3">{categoryCounts.map((item,index)=><div key={item.name}><div className="mb-1 flex justify-between text-sm"><span>{item.name}</span><span className="text-slate-500">{item.count} de {model.rows.length}</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800"><div className={`h-full rounded-full ${['bg-slate-400','bg-amber-500','bg-blue-500','bg-emerald-500'][index]}`} style={{width:`${model.rows.length?item.count/model.rows.length*100:0}%`}}/></div></div>)}</div></div>
      <div className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h3 className="font-bold">Cobertura por variable</h3><p className="mt-1 text-xs text-slate-500">Una observación puede registrar nivel 0. El objetivo se indica en cada variable.</p><div className="mt-3 space-y-2">{model.coverage.map(({variable,count,observed})=><div key={variable.id} className="border-b border-slate-100 py-2 text-sm dark:border-slate-800"><div className="flex items-center justify-between gap-2"><span className="font-medium">{variable.id} · {variable.name}</span><span className="text-[10px] text-slate-500">Objetivo: {variable.id==='B1'?'nivel 3 (todo el organismo)':variable.scale==='binary'?'nivel 3':'nivel 2+'}</span></div><div className="mt-1.5 grid grid-cols-2 gap-2 text-xs"><span className="rounded-md bg-slate-50 px-2 py-1.5 text-slate-700 dark:bg-slate-950 dark:text-slate-200">Con observación: <strong>{observed}/41</strong></span><span className="rounded-md bg-blue-50 px-2 py-1.5 text-blue-900 dark:bg-blue-950/50 dark:text-blue-100">Cumplen objetivo: <strong>{count}/41</strong></span></div></div>)}</div></div>
    </div>
  </section>;

  return <section className="space-y-5">
    <div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Monitor de Digitalización Pública</p><h2 className="mt-1 text-2xl font-extrabold">Índice de Madurez Digital Provincial</h2><p className="mt-1 max-w-3xl text-sm text-slate-500">11 variables en dos dimensiones. Los niveles sin observación se computan como 0; los valores migrados conservan una nota de origen.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>exportCsv()} className="inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-sm font-semibold"><Download size={15}/> Exportar detalle CSV</button>{canEdit&&<><input ref={importInput} className="hidden" type="file" accept=".csv,text/csv" onChange={e=>e.target.files?.[0]&&importCsv(e.target.files[0])}/><button disabled={busy} onClick={()=>importInput.current?.click()} className="inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-sm font-semibold disabled:opacity-50"><Upload size={15}/> Importar CSV</button>{baseline&&!baseline.applied&&baseline.candidates>0&&<button disabled={busy} onClick={migrateBaseline} className="inline-flex items-center gap-2 rounded-lg bg-amber-100 px-3 py-2 text-sm font-semibold text-amber-900 disabled:opacity-50">Incorporar {baseline.candidates} datos verificables</button>}{baseline?.applied&&!baseline.completeApplied&&baseline.completeCandidates>0&&<button disabled={busy} onClick={completeLegacyMigration} className="inline-flex items-center gap-2 rounded-lg bg-amber-100 px-3 py-2 text-sm font-semibold text-amber-900 disabled:opacity-50">Completar migración: {baseline.completeCandidates} registros</button>}</>}</div></div>
    {canEdit&&baseline&&!baseline.applied&&baseline.candidates>0&&<p className="rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-900">La propuesta migra niveles con correspondencia clara (web oficial, atención digital, guía de trámites, plataforma autónoma y firma digital). No convierte respuestas que no permiten identificar el nivel.</p>}
    {canEdit&&baseline?.applied&&!baseline.completeApplied&&baseline.completeCandidates>0&&<p className="rounded-lg bg-amber-50 px-3 py-2 text-xs text-amber-900">La carga integral usa también campos legados aproximables para trámites, atención, turnos, web, expediente, SIIF y firma. Los niveles quedan marcados como orientativos para que cada organismo los revise; B4, B5 y B6 no tienen campos legados equivalentes.</p>}
    {migratedCount>0&&<p role="status" className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-950 dark:border-amber-900 dark:bg-amber-950/40 dark:text-amber-100"><span><strong>Línea de base provisoria:</strong> {migratedCount} observaciones provienen del monitor anterior y requieren validación de los organismos.</span>{canEdit&&<span className="text-xs">Las nuevas observaciones quedan en el historial.</span>}</p>}
    <div className="grid gap-4 md:grid-cols-3"><article className="rounded-2xl bg-slate-900 p-5 text-white"><p className="text-xs uppercase tracking-wider text-slate-300">Índice provincial · universo de 41</p><div className="mt-2 text-4xl font-extrabold">{fmt(model.index)}<span className="text-lg"> / 100</span></div><p className="mt-1 text-sm text-blue-200">{category(model.index)}{cuts[0]&&` · ${model.index-cuts[0].snapshot.reduce((s,r)=>s+r.total,0)/PROVINCIAL_UNIVERSE>=0?'+':''}${fmt(model.index-cuts[0].snapshot.reduce((s,r)=>s+r.total,0)/PROVINCIAL_UNIVERSE)} pts vs ${cuts[0].nombre}`}</p><button onClick={()=>document.getElementById('ranking-organismos')?.scrollIntoView({behavior:'smooth',block:'start'})} className="mt-4 rounded-lg bg-white/10 px-3 py-2 text-xs font-semibold text-white hover:bg-white/20">Ir al ranking de organismos ↓</button></article><ScoreBar title="A · Servicios al ciudadano" score={model.dimensionA} max={60}/><ScoreBar title="B · Gestión interna y capacidades" score={model.dimensionB} max={40}/></div>
    <div className="grid gap-5 xl:grid-cols-[1fr_340px]"><div className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h3 className="font-bold">Cobertura por variable</h3><p className="mt-1 text-[11px] text-slate-500">Una observación puede registrar nivel 0; el objetivo de cada variable se indica en su tarjeta.</p></div><label className="text-xs text-slate-500">Orden del ranking <select className="ml-2 rounded-md border bg-transparent p-1" value={sort} onChange={e=>{setSort(e.target.value as typeof sort);setRankingPage(0)}}><option value="total">Puntaje total</option><option value="A">Dimensión A</option><option value="B">Dimensión B</option></select></label></div><div className="grid gap-4 lg:grid-cols-2">{(['A','B'] as const).map(dimension=><section key={dimension}><h4 className="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">{dimension} · {dimension==='A'?'Servicios al ciudadano':'Gestión interna y capacidades'}</h4><div className="grid gap-2">{model.coverage.filter(({variable})=>variable.dimension===dimension).map(({variable,count,observed})=><div key={variable.id} className="rounded-xl border border-slate-200 bg-white p-3 dark:border-slate-800 dark:bg-slate-950"><div className="flex flex-wrap items-start justify-between gap-x-3 gap-y-1"><span className="text-xs font-semibold">{variable.id} · {variable.name}</span><span className="text-[11px] text-slate-500">Máx. {variable.points} pts</span></div><div className="mt-3 grid grid-cols-2 gap-2"><div className="rounded-lg bg-slate-50 px-2.5 py-2 dark:bg-slate-900"><p className="text-[10px] font-medium leading-tight text-slate-500">Con observación</p><p className="mt-0.5 text-sm font-bold text-slate-800 dark:text-slate-100">{observed}<span className="ml-1 text-[10px] font-medium text-slate-500">de {PROVINCIAL_UNIVERSE}</span></p></div><div className="rounded-lg bg-blue-50 px-2.5 py-2 dark:bg-blue-950/50"><p className="text-[10px] font-medium leading-tight text-blue-700 dark:text-blue-300">Cumplen el objetivo</p><p className="mt-0.5 text-sm font-bold text-blue-900 dark:text-blue-100">{count}<span className="ml-1 text-[10px] font-medium text-blue-700 dark:text-blue-300">de {PROVINCIAL_UNIVERSE}</span></p></div></div><p className="mt-2 text-[10px] text-slate-500">Objetivo: {variable.id==='B1'?'nivel 3 (uso en todo el organismo)':variable.scale==='binary'?'nivel 3':'nivel 2 o superior'}</p></div>)}</div></section>)}</div>
      <div id="ranking-organismos" className="mt-6 scroll-mt-6 overflow-x-auto"><h3 className="mb-2 text-sm font-bold">Ranking de organismos</h3><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-b text-xs text-slate-500"><tr><th className="p-2">#</th><th className="p-2">Organismo</th><th className="p-2">Total</th><th className="p-2">A / 60</th><th className="p-2">B / 40</th><th className="p-2">Categoría</th></tr></thead><tbody>{pageRows.map((r,i)=><tr key={r.org.id} onClick={()=>setSelectedId(r.org.id)} className="cursor-pointer border-b border-slate-100 hover:bg-blue-50/60 dark:border-slate-800 dark:hover:bg-slate-800"><td className="p-2 text-slate-400">{rankingPage*RANKING_PAGE_SIZE+i+1}</td><td className="p-2 font-semibold">{r.org.nombre}</td><td className="p-2 font-mono">{fmt(r.total)}</td><td className="p-2">{fmt(r.dimensionA)}</td><td className="p-2">{fmt(r.dimensionB)}</td><td className="p-2">{category(r.total)}</td></tr>)}</tbody></table></div>
      <div className="mt-3 flex items-center justify-between gap-3 text-xs text-slate-500"><span>{sorted.length?rankingPage*RANKING_PAGE_SIZE+1:0}–{Math.min((rankingPage+1)*RANKING_PAGE_SIZE,sorted.length)} de {sorted.length} organismos</span><div className="flex items-center gap-2"><button aria-label="Página anterior" disabled={rankingPage===0} onClick={()=>setRankingPage(page=>Math.max(0,page-1))} className="rounded-md border p-1.5 disabled:opacity-40"><ChevronLeft size={16}/></button><span>Página {rankingPage+1} de {pageCount}</span><button aria-label="Página siguiente" disabled={rankingPage>=pageCount-1} onClick={()=>setRankingPage(page=>Math.min(pageCount-1,page+1))} className="rounded-md border p-1.5 disabled:opacity-40"><ChevronRight size={16}/></button></div></div>
    </div><aside className="space-y-4"><div className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h3 className="font-bold">Cortes periódicos</h3>{cuts.length?<div className="mt-3 space-y-2">{cuts.map(c=><div key={c.id} className="flex items-center justify-between gap-2 rounded-lg bg-slate-50 p-3 dark:bg-slate-950"><div><p className="font-semibold">{c.nombre}</p><p className="text-xs text-slate-500">{c.fecha}</p></div><button title="Exportar corte" onClick={()=>exportCsv(c)} className="p-2"><Download size={16}/></button></div>)}</div>:<p className="mt-2 text-sm text-slate-500">Todavía no hay cortes cerrados.</p>}{canEdit&&<div className="mt-4 space-y-2 border-t pt-4"><input className="field" placeholder="Nombre, ej. 2026-T4" value={cutName} onChange={e=>setCutName(e.target.value)}/><input className="field" type="date" value={cutDate} onChange={e=>setCutDate(e.target.value)}/><button disabled={busy||!cutName.trim()} onClick={closeCut} className="inline-flex items-center gap-2 rounded-lg bg-slate-900 px-3 py-2 text-sm font-bold text-white disabled:opacity-50"><Lock size={14}/> Cerrar corte</button></div>}</div>
      <div className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><h3 className="font-bold">Evolución del índice</h3>{cuts.length?<div className="mt-4 flex h-32 items-end gap-2">{[...cuts].reverse().map(c=>{const score=c.snapshot.length?c.snapshot.reduce((s,r)=>s+r.total,0)/c.snapshot.length:0;return <div key={c.id} className="flex h-full flex-1 flex-col items-center justify-end gap-1" title={`${c.nombre}: ${fmt(score)}`}><span className="text-[10px]">{fmt(score)}</span><div className="w-full rounded-t bg-blue-600" style={{height:`${Math.max(3,score)}%`}}/><span className="max-w-full truncate text-[9px] text-slate-500">{c.nombre}</span></div>})}</div>:<p className="mt-2 text-sm text-slate-500">Se mostrará al cerrar el primer corte.</p>}</div></aside></div>
    {error&&<p className="text-sm text-red-700">{error}</p>}{notice&&<p className="text-sm text-emerald-700">{notice}</p>}
  </section>;
}

function ScoreBar({title,score,max}:{title:string;score:number;max:number}){return <div className="rounded-2xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900"><div className="flex justify-between gap-3"><span className="text-sm font-semibold">{title}</span><span className="font-mono text-sm font-bold">{fmt(score)} <span className="text-xs text-slate-400">/ {max}</span></span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800"><div className="h-full rounded-full bg-blue-600" style={{width:`${Math.max(0,Math.min(100,score/max*100))}%`}}/></div></div>}

function Pagination({page,pageCount,total,onChange}:{page:number;pageCount:number;total:number;onChange:(page:number)=>void}){return <div className="flex items-center justify-between gap-3 text-xs text-slate-500"><span>{total?page*RANKING_PAGE_SIZE+1:0}–{Math.min((page+1)*RANKING_PAGE_SIZE,total)} de {total} organismos</span><div className="flex items-center gap-2"><button aria-label="Página anterior" disabled={page===0} onClick={()=>onChange(Math.max(0,page-1))} className="rounded-md border p-1.5 disabled:opacity-40"><ChevronLeft size={16}/></button><span>Página {page+1} de {pageCount}</span><button aria-label="Página siguiente" disabled={page>=pageCount-1} onClick={()=>onChange(Math.min(pageCount-1,page+1))} className="rounded-md border p-1.5 disabled:opacity-40"><ChevronRight size={16}/></button></div></div>}
